const INDONESIAN_INTERFACE_COPY = Object.fromEntries(
  Object.entries(ENGLISH_INTERFACE_COPY).map(([indonesian, english]) => [english, indonesian]),
) as Record<string, string>;

function translateInterfaceNode(root: Node, language: "id" | "en") {
  const dictionary = language === "en" ? ENGLISH_INTERFACE_COPY : INDONESIAN_INTERFACE_COPY;
  const translateValue = (value: string) => {
    const trimmed = value.trim();
    const translated = dictionary[trimmed];
    return translated ? value.replace(trimmed, translated) : value;
  };
  const translateTextNode = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE && node.nodeValue) {
      const translated = translateValue(node.nodeValue);
      if (translated !== node.nodeValue) node.nodeValue = translated;
    }
  };

  translateTextNode(root);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) translateTextNode(walker.currentNode);

  const elements = root instanceof Element ? [root, ...root.querySelectorAll<HTMLElement>("*")] : [];
  elements.forEach(element => {
    ["placeholder", "aria-label", "title"].forEach(attribute => {
      const value = element.getAttribute(attribute);
      if (value) element.setAttribute(attribute, translateValue(value));
    });
  });
}

// ─── Image generation ─────────────────────────────────────────────────────────
const IMAGE_KEYWORDS = [
  "gambar", "ilustrasi", "foto", "buat gambar", "generate gambar",
  "buatkan gambar", "bikin gambar", "tampilkan gambar", "render", "desain gambar",
  "tunjukkan gambar", "photo", "image", "foto saja", "output foto", "ouput foto"
];

function isImageRequest(text: string): boolean {
  const lower = text.toLowerCase().trim();
  // Cegah bentrok jika pengguna secara spesifik meminta info grafis, visualisasi data / grafik / chart, bagan, rumus, output code, file, ppt/powerpoint, link, atau kolom/tabel
  if (
    /\b(?:info\s*grafi[sk]|infografi[sk]|infographic)\b/i.test(lower) ||
    /\b(?:visualisasi\s*data|visualisasi|grafik|chart|bar\s*chart|line\s*chart|pie\s*chart|donut\s*chart|kpi)\b/i.test(lower) ||
    /\b(?:bagan|diagram|flowchart|mindmap|mind\s*map|alur proses|struktur organisasi)\b/i.test(lower) ||
    /\b(?:rumus|formula|matematika|persamaan|kalkulasi|pythagoras|turunan|integral)\b/i.test(lower) ||
    /\b(?:file|files|dokumen|lampiran|ppt|pptx|powerpoint|excel|word|pdf)\b/i.test(lower) ||
    /^(?:output\s+code|ouput\s+code|code|kode|koding|coding|output\s+link|ouput\s+link|link|tautan|url|output\s+file|ouput\s+file|file|dokumen|ppt|pptx|powerpoint|output\s+kolom|ouput\s+kolom|kolom|tabel)(?:\s+saja)?$/i.test(lower)
  ) {
    if (!/\b(?:buatkan\s+gambar|generate\s+gambar|bikin\s+gambar|foto\s+saja|output\s+foto|ouput\s+foto|tampilkan\s+foto)\b/i.test(lower)) {
      return false;
    }
  }
  return IMAGE_KEYWORDS.some(k => lower.includes(k));
}

function detectImageOrientation(text: string): "landscape" | "portrait" {
  const lower = text.toLowerCase().trim();
  // Khusus: jika pengguna mengetik "foto saja" -> LANDSCAPE
  if (lower === "foto saja" || lower.includes("foto saja") || lower.includes("lanscape") || lower.includes("landscape") || lower.includes("horizontal") || lower.includes("pemandangan")) {
    return "landscape";
  }
  // Khusus: jika pengguna mengetik "foto" -> PORTRAIT
  if (lower === "foto" || /^(?:output\s+foto|ouput\s+foto|foto)$/i.test(lower) || lower.includes("potrait") || lower.includes("portrait") || lower.includes("vertikal")) {
    return "portrait";
  }
  const landscapeKeywords = [
    "landscape", "lanscape", "horizontal", "lebar", "pemandangan", "scenery",
    "wallpaper", "alam", "gunung", "pantai", "laut", "sunset", "sunrise",
    "kota", "cityscape", "arsitektur", "danau", "langit", "ruangan", "kantor"
  ];
  const portraitKeywords = [
    "portrait", "potrait", "vertikal", "tegak", "foto diri", "orang", "manusia",
    "wisuda", "pengantin", "pernikahan", "model", "avatar", "close up", "wajah"
  ];
  if (landscapeKeywords.some(k => lower.includes(k))) return "landscape";
  if (portraitKeywords.some(k => lower.includes(k))) return "portrait";
  return "portrait";
}

