function getFeaturedPackage(featuredId?: string): ClassProgramPkg {
  if (featuredId) {
    const matched = CLASS_PROGRAM_PACKAGES.find((p) => p.id === featuredId.toLowerCase());
    if (matched) return matched;
  }
  return CLASS_PROGRAM_PACKAGES.find((p) => p.popular) ?? CLASS_PROGRAM_PACKAGES[0];
}

function formatClassProgramAsText(featuredId?: string): string {
  const pkg = getFeaturedPackage(featuredId);
  return [
    "Rekomendasi Paket Class Program Alerin",
    "",
    `${pkg.name} — ${pkg.price} (${pkg.duration.replace("*", "")}, normal ${pkg.originalPrice.replace("*", "")} · ${pkg.discountLabel})`,
    ...pkg.features.map((f) => `• ${f}`),
  ].join("\n");
}

// ─── Format Markdown Bersih untuk Disalin ke Clipboard ──────────────────────
// Merapikan teks hasil salinan agar enak dibaca di pesan chat, input, dokumen, atau WhatsApp
export function cleanMarkdownForCopy(md: string): string {
  if (!md) return "";
  let text = stripEmoticons(md);

  // Bersihkan blok paket class program menjadi ringkasan teks terstruktur
  text = text.replace(/```(?:paket-class|paket|classprogram)(?::([a-z0-9-]+))?[\s\S]*?```/gi, (_m, featuredId) => {
    return formatClassProgramAsText(featuredId);
  });

  // Bersihkan penanda tautan "Pelajari selengkapnya" pada akhir output paket
  text = text.replace(/```paket-selengkapnya[\s\S]*?```/gi, "Pelajari selengkapnya tentang semua Paket Class Program Alerin.");

  // Bersihkan blok infografis menjadi ringkasan teks terstruktur
  text = text.replace(/```(?:infografis|infographic)(?::([a-z0-9-]+))?[\s\S]*?```/gi, (_m, variant) => {
    return formatInfographicAsText(getInfographicPreset(variant));
  });

  // Bersihkan kartu visual pythagoras untuk salinan teks rapi
  text = text.replace(/```(?:visual:pythagoras|pythagoras)[\s\S]*?```/g, () => {
    return [
      "Contoh: Teorema Pythagoras",
      "a² + b² = c²",
      "",
      "Misalnya:",
      "a = 3,  b = 4",
      "c = √(3² + 4²)",
      "c = √25 = 5",
    ].join("\n");
  });

  // Bersihkan kartu visual bagan hierarki untuk salinan teks rapi
  text = text.replace(/```(?:hierarchy:organisasi|hierarchy|organisasi)[\s\S]*?```/g, () => {
    return [
      "Contoh Struktur Organisasi Perusahaan:",
      "[ Direktur Utama ]",
      "       ↓",
      "• Manager Marketing",
      "• Manager Operasional",
      "• Manager Teknologi",
    ].join("\n");
  });

  // Bersihkan blok diagram Mermaid untuk salinan teks rapi
  text = text.replace(/```mermaid([\s\S]*?)```/g, (_m, content) => {
    if (/Masukkan Email/i.test(content)) {
      return [
        "Alur Proses Login Aplikasi:",
        "1. Mulai",
        "2. Masukkan Email dan Password",
        "3. Validasi Data?",
        "   - Ya: Masuk Dashboard -> Selesai",
        "   - Tidak: Tampilkan Pesan Error -> Ulangi input email/password",
      ].join("\n");
    }
    if (/Pilih Produk/i.test(content)) {
      return "Alur Proses Pembelian: Pengguna -> Pilih Produk -> Keranjang -> Pembayaran -> Verifikasi -> Pesanan Diproses -> Produk Dikirim";
    }
    if (/Digital Marketing/i.test(content)) {
      return [
        "Mind Map Digital Marketing:",
        "• SEO: Konten, Backlink, Keyword",
        "• Social Media: Instagram, TikTok, Facebook",
        "• Advertising: Google Ads, Meta Ads",
        "• Analytics: Conversion, Traffic",
      ].join("\n");
    }
    if (/Timeline/i.test(content)) {
      return [
        "Timeline Pengembangan Produk:",
        "• Minggu 1: Research",
        "• Minggu 2: Wireframe",
        "• Minggu 3: UI Design",
        "• Minggu 4: Development",
        "• Minggu 5: Testing",
        "• Minggu 6: Launching",
      ].join("\n");
    }
    return content.trim();
  });

  // Bersihkan kartu visualisasi data untuk salinan teks rapi
  text = text.replace(/```(?:chart:bar|barchart)[\s\S]*?```/g, () => {
    return [
      "Pertumbuhan Pengguna Aplikasi:",
      "• Januari: 120",
      "• Februari: 180",
      "• Maret: 250",
      "• April: 310",
      "• Mei: 420",
      "• Juni: 560",
    ].join("\n");
  });

  text = text.replace(/```(?:chart:line|linechart)[\s\S]*?```/g, () => {
    return "Tren Penjualan 2026: Penjualan tertinggi mencapai Rp35 juta pada bulan Juni.";
  });

  text = text.replace(/```(?:chart:pie|chart:donut|piechart)[\s\S]*?```/g, () => {
    return [
      "Distribusi Pengguna Berdasarkan Perangkat:",
      "• Mobile: 650 (65%)",
      "• Desktop: 280 (28%)",
      "• Tablet: 70 (7%)",
    ].join("\n");
  });

  text = text.replace(/```(?:chart:comparison|comparison)[\s\S]*?```/g, () => {
    return [
      "Target vs Realisasi Penjualan:",
      "• Januari: Target Rp20 jt | Realisasi Rp18 jt",
      "• Februari: Target Rp25 jt | Realisasi Rp28 jt",
      "• Maret: Target Rp30 jt | Realisasi Rp27 jt",
      "• April: Target Rp35 jt | Realisasi Rp40 jt",
      "• Mei: Target Rp40 jt | Realisasi Rp45 jt",
    ].join("\n");
  });

  text = text.replace(/```(?:chart:kpi|kpi)[\s\S]*?```/g, () => {
    return [
      "Ringkasan KPI Bisnis:",
      "• Total pengguna: 1.250 (+18,5%)",
      "• Total transaksi: 845 (+12,2%)",
      "• Conversion rate: 6,8% (+2,1%)",
      "• Pendapatan: Rp45 jt (+15,4%)",
    ].join("\n");
  });

  // Bersihkan blok lampiran file agar saat disalin rapi berbentuk poin-poin
  text = text.replace(/```(?:files|file|lampiran)[\r\n]+([\s\S]*?)```/g, (_m, content) => {
    return content
      .trim()
      .split("\n")
      .map((line) => {
        const parts = line.split("|").map((p) => p.trim());
        if (parts.length >= 2) {
          return `• ${parts[0]} (${parts[1]})`;
        }
        return line;
      })
      .join("\n");
  });

  // 1. Bersihkan blok kode / links / penulisan
  text = text.replace(/```(?:links)\n([\s\S]*?)```/g, (_m, content) => content.trim());
  text = text.replace(/```[a-zA-Z0-9_-]*\n([\s\S]*?)```/g, (_m, code) => code.trim());
  text = text.replace(/```/g, "");
  text = text.replace(/\^\^([^\n]+)\^\^/g, "$1");
  text = text.replace(/\[\[([^|\]]+)\|[^\]]+\]\]/g, "$1");

  // Bersihkan notasi KaTeX / LaTeX untuk salin teks yang rapi dan mudah dibaca
  text = text.replace(/\\boxed\{([^}]+)\}/g, "[$1]");
  text = text.replace(/\\frac\{([^}]+)\}\{([^}]+)\}/g, "($1) / ($2)");
  text = text.replace(/\\sqrt\{([^}]+)\}/g, "√($1)");
  text = text.replace(/\\pi\b/g, "π");
  text = text.replace(/\\times\b/g, "×");
  text = text.replace(/\\pm\b/g, "±");
  text = text.replace(/\\text\{([^}]+)\}/g, "$1");
  text = text.replace(/\\quad\b/g, "  ");
  text = text.replace(/\$\$([\s\S]*?)\$\$/g, "$1");
  text = text.replace(/\$([^$\n]+)\$/g, "$1");

  // 2. Format tabel markdown menjadi baris teks rapi
  text = text.replace(/^\|?\s*[-:]+[-| :]*\s*\|?$/gm, "");
  text = text.replace(/^\|(.*)\|$/gm, (_m, row) => {
    return row.split("|").map((col: string) => col.trim()).filter(Boolean).join("  ·  ");
  });

  // 3. Bersihkan judul / heading markdown (## Judul -> Judul)
  text = text.replace(/^#{1,6}\s+(.*)$/gm, "$1");

  // 4. Bersihkan penanda tebal & miring (**teks** / *teks* / __teks__ -> teks)
  text = text.replace(/\*\*\*(.*?)\*\*\*/g, "$1");
  text = text.replace(/\*\*(.*?)\*\*/g, "$1");
  text = text.replace(/__(.*?)__/g, "$1");
  text = text.replace(/\*([^*\n]+)\*/g, "$1");
  text = text.replace(/_([^_\n]+)_/g, "$1");
  text = text.replace(/~~(.*?)~~/g, "$1");
  text = text.replace(/`([^`\n]+)`/g, "$1");

  // 5. Tautan markdown [Label](url) -> Label (url)
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, label, url) => {
    return label === url ? label : `${label} (${url})`;
  });

  // 6. Rapikan list / poin bullet (- item atau * item -> • item)
  text = text.replace(/^[-*]\s+/gm, "• ");
  text = text.replace(/^(\d+)\.\s*/gm, "$1. ");

  // 7. Bersihkan kutipan blockquote (> teks -> teks)
  text = text.replace(/^>\s*/gm, "");

  // 8. Normalisasi jarak baris antar paragraf
  text = text
    .replace(/[ \t]+$/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  return text;
}

// ─── Render Pesan Pengguna (Mendukung baris baru & styling rapi) ───────────────
function renderUserMessageContent(text: string) {
  if (!text) return null;
  // Parse inline bold **teks** dan *miring* jika pengguna mengirim format markdown
  const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
  return parts.map((part, idx) => {
    if (part.startsWith("**") && part.endsWith("**") && part.length >= 4) {
      return (
        <strong key={idx} className="font-semibold text-slate-950">
          {part.slice(2, -2)}
        </strong>
      );
    }
    if (part.startsWith("*") && part.endsWith("*") && part.length >= 2) {
      return (
        <em key={idx} className="italic">
          {part.slice(1, -1)}
        </em>
      );
    }
    return part;
  });
}

