// ─── Highlight bold keyword in text ─────────────────────────────────────────
function Highlight({ text, query }: { text: string; query: string }) {
  if (!query.trim()) return <>{text}</>;
  const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi");
  const parts = text.split(regex);
  return (
    <>
      {parts.map((p, i) =>
        regex.test(p) ? <strong key={i} className="font-bold text-slate-900">{p}</strong> : <span key={i}>{p}</span>
      )}
    </>
  );
}

type RiwayatItem = {
  id: string;
  title: string;
  time: string;
  msgs: ChatMsg[];
  pinned?: boolean;
};

const ChatBubbleIcon = () => (
  <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round">
    <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>
  </svg>
);

// ─── Search Modal ─────────────────────────────────────────────────────────────
function SearchModal({
  onClose,
  onSelect,
  historyItems,
}: {
  onClose: () => void;
  onSelect?: (title: string, itemType?: "chat" | "dokumen" | "proyek", itemId?: string) => void;
  historyItems?: RiwayatItem[];
}) {
  const [query, setQuery] = useState("");
  const [filter, setFilter] = useState<SearchFilter>("semua");
  const [showRecentChats, setShowRecentChats] = useState(true);
  const inputRef = useRef<HTMLInputElement>(null);
  const hasQuery = query.trim().length > 0;

  // Isi list "Obrolan terbaru" disamakan langsung dengan riwayat obrolan pengguna
  const recentChats = (historyItems && historyItems.length > 0)
    ? historyItems.map((h) => h.title)
    : DEFAULT_RIWAYAT_ITEMS.map((h) => h.title);

  useEffect(() => {
    inputRef.current?.focus();
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const FILTERS: { id: SearchFilter; label: string }[] = [
    { id: "semua", label: "Semua" },
    { id: "chat", label: "Obrolan" },
    { id: "dokumen", label: "Dokumen" },
    { id: "proyek", label: "Proyek" },
  ];

  // 1. Data pencarian obrolan (dari riwayat obrolan pengguna)
  const chatSearchItems = (historyItems && historyItems.length > 0 ? historyItems : DEFAULT_RIWAYAT_ITEMS).map((item, idx) => ({
    id: `chat-${item.id || idx}`,
    type: "chat" as const,
    title: item.title,
    snippet: item.msgs?.[0]?.text || item.title,
    date: item.time || "Terbaru",
    keyword: "",
  }));

  // 2. Data pencarian proyek (sinkron langsung dari penyimpanan proyek pengguna & proyek bawaan)
  const userProjects = useMemo(() => loadUserProjectsList(), []);

  const projectSearchItems = useMemo(() => {
    let projChatsMap: Record<string, { title: string; msgs: ChatMsg[] }[]> = {};
    if (typeof window !== "undefined") {
      try {
        const savedChats = localStorage.getItem("alerin_mobile_project_chats");
        if (savedChats) projChatsMap = JSON.parse(savedChats);
      } catch {}
    }

    return userProjects.map((p) => {
      const extraChats = projChatsMap[p.id] || [];
      const extraChatTitles = extraChats.map((c) => c.title).join(" · ");
      const firstMsg = p.msgs?.[0]?.text;
      let snippet = `Proyek aktif · ${p.time || "terakhir diperbarui"}`;
      if (extraChatTitles) {
        snippet = `Proyek aktif · ${extraChatTitles}`;
      } else if (firstMsg) {
        snippet = `Proyek aktif · ${firstMsg}`;
      }
      return {
        id: p.id,
        type: "proyek" as const,
        title: p.title,
        snippet,
        date: p.time ? p.time.replace("Terakhir diperbarui ", "").replace(" yang lalu", "") : "Terbaru",
        keyword: p.title,
      };
    });
  }, [userProjects]);

  const allSearchData = [
    ...chatSearchItems,
    ...projectSearchItems,
    ...SEARCH_HISTORY.filter((item) => item.type === "dokumen"),
  ];

  const filtered = allSearchData.filter((item) => {
    const matchFilter = filter === "semua" || item.type === filter;
    const q = query.trim().toLowerCase();
    const matchQuery = !q ||
      item.title.toLowerCase().includes(q) ||
      item.snippet.toLowerCase().includes(q);
    return matchFilter && matchQuery;
  });

  const typeIcon = (type: string) => {
    if (type === "dokumen") return (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
    );
    if (type === "proyek") return (
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M4 20h16a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.93a2 2 0 0 1-1.66-.9l-.82-1.2A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13c0 1.1.9 2 2 2Z"/></svg>
    );
    return <ChatBubbleIcon />;
  };

  return (
    <div
      className="fixed inset-0 z-[250] flex items-start justify-center p-4 pt-14 sm:pt-20 bg-black/45 backdrop-blur-xs animate-[gemini-fade-in_0.15s_ease-out]"
      onClick={onClose}
    >
      <div
        className="w-full max-w-[350px] sm:max-w-lg rounded-3xl overflow-hidden bg-white shadow-2xl border border-slate-100 flex flex-col animate-[gemini-zoom-in_0.2s_ease-out]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Search input row */}
        <div className="flex items-center gap-3 px-5 py-3.5 border-b border-slate-100/60">
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(capitalizeWords(e.target.value))}
            autoCapitalize="sentences"
            autoCorrect="on"
            spellCheck={false}
            onKeyDown={(e) => {
              if (e.key === "Enter" && query.trim()) {
                if (filtered.length > 0) {
                  onSelect?.(filtered[0].title, filtered[0].type, filtered[0].id);
                } else {
                  onSelect?.(query.trim());
                }
                onClose();
              }
            }}
            placeholder="Cari..."
            className="flex-1 bg-transparent text-slate-800 text-[15px] placeholder-slate-400 outline-none"
          />
          <button
            type="button"
            onClick={onClose}
            aria-label="Tutup pencarian"
            className="size-8 rounded-full flex items-center justify-center text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors cursor-pointer shrink-0"
          >
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        </div>

        {/* ── Empty state: Obrolan terbaru ── */}
        {!hasQuery && (
          <div className="pb-3 pt-1.5 max-h-[60vh] overflow-y-auto [&::-webkit-scrollbar]:hidden" style={{ scrollbarWidth: "none" }}>
            <button
              type="button"
              onClick={() => setShowRecentChats((prev) => !prev)}
              className="w-full flex items-center justify-between px-5 pb-2 pt-1 text-xs font-semibold text-slate-400 hover:text-slate-600 transition-colors cursor-pointer select-none text-left"
              title="Klik untuk melihat simulasi tampilan kosong obrolan"
            >
              <span>Riwayat pencarian</span>
            </button>
            {showRecentChats && recentChats.length > 0 ? (
              recentChats.map((title) => (
                <button
                  key={title}
                  type="button"
                  onClick={() => {
                    onSelect?.(title, "chat");
                    onClose();
                  }}
                  className="w-full flex items-center gap-3 px-5 py-2.5 hover:bg-slate-50 active:bg-slate-100 transition-colors text-left group cursor-pointer"
                >
                  <span className="text-slate-400 group-hover:text-slate-600 transition-colors shrink-0">
                    <ChatBubbleIcon />
                  </span>
                  <span className="text-sm text-slate-700 group-hover:text-slate-900 transition-colors truncate">{title}</span>
                </button>
              ))
            ) : (
              <div className="py-10 px-6 flex flex-col items-center justify-center text-center animate-[gemini-fade-in_0.2s_ease-out]">
                <div className="size-13 rounded-2xl bg-slate-50 border border-slate-200/80 flex items-center justify-center mb-3 shadow-2xs text-slate-400">
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
                    <line x1="9" y1="10" x2="15" y2="10" />
                  </svg>
                </div>
                <h4 className="text-[14.5px] font-bold text-slate-800 tracking-tight">Tidak ada riwayat</h4>
                <p className="text-xs text-slate-400 font-normal leading-relaxed mt-1 max-w-[220px]">
                  Belum ada riwayat pencarian terbaru
                </p>
              </div>
            )}
          </div>
        )}

        {/* ── Has query: filter tabs + results ── */}
        {hasQuery && (
          <>
            {/* Filter tabs */}
            <div className="flex items-center gap-1 px-4 pb-2 border-b border-slate-100">
              {FILTERS.map((f) => (
                <button
                  key={f.id}
                  onClick={() => setFilter(f.id)}
                  className="px-4 py-1.5 rounded-full text-xs font-semibold transition-all cursor-pointer"
                  style={filter === f.id
                    ? { background: "#3b82f6", color: "#fff" }
                    : { color: "#64748b", background: "transparent" }}
                >
                  {f.label}
                </button>
              ))}
            </div>

            {/* Results */}
            <div className="max-h-80 overflow-y-auto py-1">
              {filtered.length === 0 ? (
                <div className="px-5 py-10 text-center">
                  <p className="text-slate-400 text-sm">Tidak ada hasil untuk "<span className="text-slate-700">{query}</span>"</p>
                </div>
              ) : (
                filtered.map((item) => (
                  <button
                    key={item.id}
                    onClick={() => {
                      onSelect?.(item.title, item.type, item.id);
                      onClose();
                    }}
                    className="w-full flex items-start gap-3 px-5 py-3.5 hover:bg-slate-50 transition-colors text-left group cursor-pointer"
                  >
                    <span className="text-slate-400 group-hover:text-slate-600 transition-colors mt-0.5 shrink-0">
                      {typeIcon(item.type)}
                    </span>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="text-sm font-semibold text-slate-700 group-hover:text-slate-900 transition-colors truncate">
                          <Highlight text={item.title} query={query} />
                        </p>
                        {item.type === "proyek" && filter === "semua" && (
                          <span className="text-[10px] font-medium px-1.5 py-0.5 rounded-md bg-blue-50 text-blue-600 shrink-0">
                            Proyek
                          </span>
                        )}
                        {item.type === "dokumen" && filter === "semua" && (
                          <span className="text-[10px] font-medium px-1.5 py-0.5 rounded-md bg-amber-50 text-amber-700 shrink-0">
                            Dokumen
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-slate-400 truncate mt-0.5">
                        <Highlight text={item.snippet} query={query} />
                      </p>
                    </div>
                    <span className="text-xs text-slate-400 shrink-0 mt-0.5">{item.date}</span>
                  </button>
                ))
              )}
            </div>
          </>
        )}
      </div>
    </div>
  );
}

