// ─── Shared Modal Pilih & Salin Teks ─────────────────────────────────────────
function SelectTextModal({
  text,
  onClose,
  onCopied,
}: {
  text: string | null;
  onClose: () => void;
  onCopied: (message: string) => void;
}) {
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const [allSelected, setAllSelected] = useState(false);

  useEffect(() => {
    setAllSelected(false);
  }, [text]);

  if (text === null) return null;

  const syncAllSelectedState = (el: HTMLTextAreaElement) => {
    setAllSelected(el.value.length > 0 && el.selectionStart === 0 && el.selectionEnd === el.value.length);
  };

  const selectAllInTextarea = (el: HTMLTextAreaElement) => {
    el.focus();
    el.select();
    try { el.setSelectionRange(0, el.value.length); } catch {}
    setAllSelected(true);
  };

  const handleToggleSelectAll = () => {
    const el = textareaRef.current;
    if (!el) return;
    const isCurrentlyAll =
      allSelected || (el.value.length > 0 && el.selectionStart === 0 && el.selectionEnd === el.value.length);
    if (isCurrentlyAll) {
      try { el.setSelectionRange(0, 0); } catch {}
      el.blur();
      try { window.getSelection()?.removeAllRanges(); } catch {}
      setAllSelected(false);
    } else {
      selectAllInTextarea(el);
    }
  };

  const handleCopy = () => {
    const el = textareaRef.current;
    let textToCopy = text || "";
    let isPartial = false;
    if (el && el.selectionStart !== el.selectionEnd && (el.selectionStart !== 0 || el.selectionEnd !== el.value.length)) {
      textToCopy = el.value.substring(el.selectionStart, el.selectionEnd);
      isPartial = true;
    }
    const cleanToCopy = cleanMarkdownForCopy(textToCopy);
    if (navigator?.clipboard?.writeText) {
      navigator.clipboard.writeText(cleanToCopy).then(() => {
        onCopied(isPartial ? "Bagian teks disalin!" : "Teks berhasil disalin!");
        onClose();
      }).catch(() => {
        onCopied("Teks disalin!");
        onClose();
      });
    } else {
      onCopied("Teks disalin!");
      onClose();
    }
  };

  return (
    <div
      className="fixed inset-0 z-[270] flex items-center justify-center p-4 bg-black/45 backdrop-blur-xs animate-[gemini-fade-in_0.15s_ease-out]"
      onClick={onClose}
    >
      <div
        className="w-full max-w-[440px] bg-white rounded-3xl p-5 shadow-2xl border border-slate-100 flex flex-col gap-3.5 animate-[gemini-zoom-in_0.2s_ease-out]"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center gap-2.5">
          <div className="size-8 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="4" y1="7" x2="4" y2="4"/>
              <line x1="4" y1="4" x2="7" y2="4"/>
              <line x1="20" y1="7" x2="20" y2="4"/>
              <line x1="20" y1="4" x2="17" y2="4"/>
              <line x1="4" y1="17" x2="4" y2="20"/>
              <line x1="4" y1="20" x2="7" y2="20"/>
              <line x1="20" y1="17" x2="20" y2="20"/>
              <line x1="20" y1="20" x2="17" y2="20"/>
              <line x1="9" y1="9" x2="15" y2="9"/>
              <line x1="12" y1="9" x2="12" y2="15"/>
              <line x1="9" y1="15" x2="15" y2="15"/>
            </svg>
          </div>
          <div>
            <h3 className="text-base font-bold text-slate-900 leading-tight">Pilih Teks</h3>
            <p className="text-[11px] text-slate-500">Sorot bagian teks atau salin semua teks di bawah</p>
          </div>
        </div>

        <div className="relative">
          <textarea
            ref={textareaRef}
            readOnly
            value={text}
            onClick={(e) => {
              const el = e.currentTarget;
              if (el.value.length > 0 && el.selectionStart === el.selectionEnd) {
                selectAllInTextarea(el);
              } else {
                syncAllSelectedState(el);
              }
            }}
            onSelect={(e) => syncAllSelectedState(e.currentTarget)}
            onMouseUp={(e) => syncAllSelectedState(e.currentTarget)}
            onKeyUp={(e) => syncAllSelectedState(e.currentTarget)}
            className="w-full h-[225px] min-h-[180px] max-h-[380px] p-3.5 text-sm leading-relaxed text-slate-900 bg-white border-2 border-[#1A73E8] rounded-2xl ring-2 ring-[#1A73E8]/20 focus:outline-none focus:ring-2 focus:ring-[#1A73E8] selection:bg-[#BCE3FA] selection:text-slate-900 select-text cursor-text resize-none font-normal transition-all"
          />
        </div>

        <div className="flex items-center justify-between gap-2 pt-1 border-t border-slate-100">
          <button
            type="button"
            onClick={handleToggleSelectAll}
            className={`px-3 py-2 text-xs font-medium rounded-xl transition-colors flex items-center gap-1.5 cursor-pointer ${
              allSelected
                ? "bg-blue-50 text-blue-700 hover:bg-blue-100 active:bg-blue-200"
                : "text-blue-600 hover:bg-blue-50 active:bg-blue-100"
            }`}
          >
            <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <rect x="3" y="3" width="18" height="18" rx="2"/>
              <path d="M9 3v18"/>
            </svg>
            Pilih Semua
          </button>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-3.5 py-2 text-xs font-medium text-slate-600 hover:bg-slate-100 active:bg-slate-200 rounded-xl transition-colors cursor-pointer"
            >
              Tutup
            </button>
            <button
              type="button"
              onClick={handleCopy}
              className="px-4 py-2 text-xs font-semibold text-white bg-[#1A73E8] hover:bg-[#1557b0] active:bg-[#134c9a] rounded-xl transition-colors shadow-xs flex items-center gap-1.5 cursor-pointer"
            >
              <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
              </svg>
              Salin
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Shared User Bubble Long-Press Hook & Action Menu ────────────────────────
function useUserBubbleLongPress(getRoleAt: (idx: number) => string | undefined) {
  const [activeIdx, setActiveIdx] = useState<number | null>(null);
  const [placement, setPlacement] = useState<"top" | "bottom">("top");
  const [anchorPos, setAnchorPos] = useState<{ x: number; y: number } | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const startPosRef = useRef<{ x: number; y: number } | null>(null);
  const getRoleRef = useRef(getRoleAt);
  getRoleRef.current = getRoleAt;

  const clearTimer = useCallback(() => {
    if (timerRef.current) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  useEffect(() => clearTimer, [clearTimer]);

  const openMenuForTarget = useCallback(
    (idx: number, target: HTMLDivElement, vibrate = false, point?: { x: number; y: number }) => {
      if (vibrate && typeof navigator !== "undefined" && navigator.vibrate) {
        try { navigator.vibrate(40); } catch (_) {}
      }
      const rect = target.getBoundingClientRect();
      const vh = typeof window !== "undefined" ? window.innerHeight : 844;
      const resolvedPoint = point ?? {
        x: rect.right - 24,
        y: Math.min(Math.max(rect.top + 24, 80), vh - 160),
      };
      setPlacement(resolvedPoint.y < 220 ? "bottom" : "top");
      setAnchorPos(resolvedPoint);
      setActiveIdx(idx);
      timerRef.current = null;
    },
    []
  );

  const getBubbleInteractionProps = useCallback((idx: number) => ({
    onTouchStart: (e: React.TouchEvent<HTMLDivElement>) => {
      if (getRoleRef.current(idx) !== "user") return;
      const touch = e.touches[0];
      const point = { x: touch.clientX, y: touch.clientY };
      startPosRef.current = point;
      clearTimer();
      const target = e.currentTarget;
      timerRef.current = setTimeout(() => openMenuForTarget(idx, target, true, point), 450);
    },
    onTouchMove: (e: React.TouchEvent<HTMLDivElement>) => {
      if (!startPosRef.current || !timerRef.current) return;
      const touch = e.touches[0];
      const dx = Math.abs(touch.clientX - startPosRef.current.x);
      const dy = Math.abs(touch.clientY - startPosRef.current.y);
      if (dx > 10 || dy > 10) clearTimer();
    },
    onTouchEnd: clearTimer,
    onTouchCancel: clearTimer,
    onMouseDown: (e: React.MouseEvent<HTMLDivElement>) => {
      if (e.button !== 0 || getRoleRef.current(idx) !== "user") return;
      const point = { x: e.clientX, y: e.clientY };
      startPosRef.current = point;
      clearTimer();
      const target = e.currentTarget;
      timerRef.current = setTimeout(() => openMenuForTarget(idx, target, false, point), 450);
    },
    onMouseMove: (e: React.MouseEvent<HTMLDivElement>) => {
      if (!startPosRef.current || !timerRef.current) return;
      const dx = Math.abs(e.clientX - startPosRef.current.x);
      const dy = Math.abs(e.clientY - startPosRef.current.y);
      if (dx > 8 || dy > 8) clearTimer();
    },
    onMouseUp: clearTimer,
    onMouseLeave: clearTimer,
    onContextMenu: (e: React.MouseEvent<HTMLDivElement>) => {
      e.preventDefault();
      clearTimer();
      if (getRoleRef.current(idx) !== "user") return;
      openMenuForTarget(idx, e.currentTarget, false, { x: e.clientX, y: e.clientY });
    },
  }), [clearTimer, openMenuForTarget]);

  return { activeIdx, setActiveIdx, placement, anchorPos, getBubbleInteractionProps };
}

function UserBubbleActionMenu({
  open,
  placement,
  anchorPos,
  showEdit,
  onClose,
  onCopy,
  onEdit,
  onSelectText,
}: {
  open: boolean;
  placement: "top" | "bottom";
  anchorPos?: { x: number; y: number } | null;
  showEdit: boolean;
  onClose: () => void;
  onCopy: () => void;
  onEdit: () => void;
  onSelectText: () => void;
}) {
  if (!open || typeof document === "undefined") return null;

  const menuWidth = 176;
  const estimatedHeight = showEdit ? 136 : 96;
  const margin = 12;
  const gap = 14;
  const vw = typeof window !== "undefined" ? window.innerWidth : 390;
  const vh = typeof window !== "undefined" ? window.innerHeight : 844;
  const x = anchorPos ? anchorPos.x : vw - margin - menuWidth / 2;
  const y = anchorPos ? anchorPos.y : vh / 2;
  const left = Math.max(margin, Math.min(x - menuWidth / 2, vw - menuWidth - margin));
  const preferTop = placement === "top" && y - estimatedHeight - gap >= margin;
  const rawTop = preferTop ? y - estimatedHeight - gap : y + gap;
  const top = Math.max(margin, Math.min(rawTop, vh - estimatedHeight - margin));

  return createPortal(
    <>
      <div
        className="fixed inset-0 z-[250] bg-transparent"
        onMouseDown={onClose}
        onTouchStart={onClose}
      />
      <div
        style={{ left: `${left}px`, top: `${top}px` }}
        className="fixed z-[251] bg-white rounded-2xl border border-slate-200/90 shadow-[0_12px_36px_rgba(0,0,0,0.18)] p-1.5 w-44 flex flex-col gap-0.5 text-xs animate-in fade-in zoom-in-95"
        onClick={(e) => e.stopPropagation()}
        onPointerDown={(e) => e.stopPropagation()}
        onTouchStart={(e) => e.stopPropagation()}
        onTouchEnd={(e) => e.stopPropagation()}
        onMouseDown={(e) => e.stopPropagation()}
      >
        {/* 1. Salin */}
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onCopy();
          }}
          onPointerDown={(e) => e.stopPropagation()}
          onMouseDown={(e) => e.stopPropagation()}
          className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-left font-medium text-slate-700 hover:bg-slate-100/90 active:bg-slate-100 transition-colors cursor-pointer"
        >
          <svg className="w-4 h-4 text-slate-500 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
            <rect x="9" y="9" width="13" height="13" rx="2" ry="2" />
            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
          </svg>
          <span>Salin</span>
        </button>

        {/* 2. Edit (Hanya untuk bubble user terbaru) */}
        {showEdit && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onEdit();
            }}
            onPointerDown={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-left font-medium text-slate-700 hover:bg-slate-100/90 active:bg-slate-100 transition-colors cursor-pointer"
          >
            <svg className="w-4 h-4 text-slate-500 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M12 20h9"/>
              <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>
            </svg>
            <span>Edit</span>
          </button>
        )}

        {/* 3. Pilih teks */}
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onSelectText();
          }}
          onPointerDown={(e) => e.stopPropagation()}
          onMouseDown={(e) => e.stopPropagation()}
          className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl text-left font-medium text-slate-700 hover:bg-slate-100/90 active:bg-slate-100 transition-colors cursor-pointer"
        >
          <svg className="w-4 h-4 text-slate-500 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
            <line x1="4" y1="7" x2="4" y2="4"/>
            <line x1="4" y1="4" x2="7" y2="4"/>
            <line x1="20" y1="7" x2="20" y2="4"/>
            <line x1="20" y1="4" x2="17" y2="4"/>
            <line x1="4" y1="17" x2="4" y2="20"/>
            <line x1="4" y1="20" x2="7" y2="20"/>
            <line x1="20" y1="17" x2="20" y2="20"/>
            <line x1="20" y1="20" x2="17" y2="20"/>
            <line x1="9" y1="9" x2="15" y2="9"/>
            <line x1="12" y1="9" x2="12" y2="15"/>
            <line x1="9" y1="15" x2="15" y2="15"/>
          </svg>
          <span>Pilih teks</span>
        </button>
      </div>
    </>,
    document.body
  );
}

